import { useState, useEffect } from "react";
import axios from "axios";

const VetHistory = () => {
  const [history, setHistory] = useState([]);

  useEffect(() => {
    axios.get("http://localhost:5000/api/appointments/history?status=Completed,Cancelled")
      .then((response) => setHistory(response.data))
      .catch((error) => console.error("Error fetching history:", error));
  }, []);

  return (
    <div className="bg-white p-6 rounded-lg shadow-md">
      <h2 className="text-2xl font-bold mb-4">Appointment History</h2>
      <table className="w-full border">
        <thead>
          <tr className="bg-gray-100">
            <th className="p-2 border">Appointment ID</th>
            <th className="p-2 border">Owner Name</th>
            <th className="p-2 border">Pet Name (Type)</th>
            <th className="p-2 border">Services</th>
            <th className="p-2 border">Date</th>
          </tr>
        </thead>
        <tbody>
          {history.map((apt) => (
            <tr key={apt._id} className="border">
              <td className="p-2 border">{apt._id}</td>
              <td className="p-2 border">{apt.ownerName}</td>
              <td className="p-2 border">{apt.petName} ({apt.petType})</td>
              <td className="p-2 border">{apt.services.join(", ")}</td>
              <td className="p-2 border">{new Date(apt.date).toLocaleString()}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default VetHistory;
